        imageUrl: `img${i}`,
      })),
    );
    const { fetchMock, calls, getMaxInFlight } = controllableFetch();
    vi.stubGlobal("fetch", fetchMock);

    const { result } = renderHook(() => useLibraryArtists("token-1"));

